import { FormEvent, ReactNode, useEffect, useMemo, useRef, useState } from "react";
import { Link, Navigate, Route, Routes, useLocation, useNavigate, useParams } from "react-router-dom";
import { CircleMarker, MapContainer, Polyline, Popup, TileLayer } from "react-leaflet";
import "leaflet/dist/leaflet.css";
import {
  Activity, AlertTriangle, Bell, Boxes, ChevronRight, CircleUserRound, ClipboardList, Globe2,
  HeartPulse, LayoutDashboard, LogOut, MapPinned, Menu, PackageCheck, Plus, RefreshCw,
  ShieldCheck, Sparkles, Truck, Users, Warehouse as WarehouseIcon, X,
} from "lucide-react";
import {
  Allocation, api, AuthResponse, Language, Notification, PriorityQueue, Report, RoutePlan, Team, Trends,
  RoadRisk, User, VehicleTracking, Volunteer, Warehouse,
} from "./api";

type Session = { token: string; user: User };
type AppContext = {
  session: Session; language: string; languages: Language[]; t: (key: string, fallback?: string) => string;
  refreshUser: () => Promise<void>; signOut: () => void;
};

const sessionKey = "responda_session";
const languageKey = "responda_language";

function useAsync<T>(load: () => Promise<T>, deps: unknown[] = []) {
  const [data, setData] = useState<T>();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const hasData = useRef(false);
  const refresh = async (silent = false) => {
    if (!silent) { setLoading(true); setError(""); }
    try { const result = await load(); hasData.current = true; setData(result); }
    catch (cause) { if (!silent || !hasData.current) setError(cause instanceof Error ? cause.message : "Unable to load data."); }
    finally { if (!silent) setLoading(false); }
  };
  useEffect(() => { void refresh(); }, deps); // eslint-disable-line react-hooks/exhaustive-deps
  return { data, loading, error, refresh, setData };
}

function App() {
  const [session, setSession] = useState<Session | null>(() => {
    try { return JSON.parse(localStorage.getItem(sessionKey) || "null"); } catch { return null; }
  });
  const [language, setLanguage] = useState(() => localStorage.getItem(languageKey) || "en");
  const languageData = useAsync(api.languages, []);
  const bundle = useAsync(() => api.bundle(language), [language]);
  const t = (key: string, fallback?: string) => bundle.data?.translations[key] || fallback || key;
  const saveSession = (next: Session | null) => {
    setSession(next);
    next ? localStorage.setItem(sessionKey, JSON.stringify(next)) : localStorage.removeItem(sessionKey);
  };
  const changeLanguage = (code: string) => { setLanguage(code); localStorage.setItem(languageKey, code); };
  useEffect(() => {
    const expire = () => saveSession(null);
    window.addEventListener("responda:session-expired", expire);
    return () => window.removeEventListener("responda:session-expired", expire);
  }, []);
  const refreshUser = async () => {
    if (!session) return;
    const user = await api.me(session.token, language);
    saveSession({ ...session, user });
  };

  if (!session) return <AuthShell language={language} languages={languageData.data?.supported || []} changeLanguage={changeLanguage} t={t} onAuth={(result) => saveSession({ token: result.access_token, user: result.user })} />;
  const context: AppContext = { session, language, languages: languageData.data?.supported || [], t, refreshUser, signOut: () => saveSession(null) };
  return <ProtectedLayout context={context} onLanguage={changeLanguage} />;
}

function AuthShell({ language, languages, changeLanguage, t, onAuth }: { language: string; languages: Language[]; changeLanguage: (code: string) => void; t: (key: string, fallback?: string) => string; onAuth: (result: AuthResponse) => void }) {
  const location = useLocation();
  const navigate = useNavigate();
  const [registerMode, setRegisterMode] = useState(location.pathname === "/register");
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState("");
  useEffect(() => setRegisterMode(location.pathname === "/register"), [location.pathname]);
  const submit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); setBusy(true); setMessage("");
    const values = Object.fromEntries(new FormData(event.currentTarget));
    try {
      if (registerMode) {
        if (values.password !== values.confirm_password) throw new Error(t("auth.passwords_not_match", "Passwords do not match."));
        await api.register({ email: String(values.email), full_name: String(values.full_name), password: String(values.password) }, language);
        setMessage(t("auth.registration_success", "Registration successful. Please sign in."));
        setRegisterMode(false); navigate("/login");
      } else {
        onAuth(await api.login({ email: String(values.email), password: String(values.password) }, language));
      }
    } catch (cause) { setMessage(cause instanceof Error ? cause.message : "Something went wrong."); }
    finally { setBusy(false); }
  };
  return <main className="auth-page">
    <section className="auth-hero">
      <div className="brand brand-light"><span className="brand-mark"><HeartPulse size={21} /></span> {t("auth.hero_brand", "AI-Based Disaster Response Management System")}</div>
      <div className="hero-copy"><span className="eyebrow"><Sparkles size={15} /> {t("auth.hero_eyebrow", "AI-powered resilience platform")}</span><h1>{t("auth.hero_title", "Turn urgency into")} <em>{t("auth.hero_emphasis", "coordinated action.")}</em></h1><p>{t("auth.hero_description", "One operational command center for disaster intelligence, resource logistics, and field response.")}</p></div>
      <div className="hero-orb orb-one" /><div className="hero-orb orb-two" />
      <div className="hero-stats"><span><b>24/7</b> {t("auth.incident_readiness", "Incident readiness")}</span><span><b>22</b> {t("auth.indian_languages", "Indian languages")}</span><span><b>Live</b> {t("auth.operations_signal", "Operations signal")}</span></div>
    </section>
    <section className="auth-card-wrap">
      <div className="auth-language"><Globe2 size={16} /><select value={language} onChange={(e) => changeLanguage(e.target.value)}>{languages.map((item) => <option key={item.code} value={item.code}>{item.name}</option>)}</select></div>
      <form className="auth-card" onSubmit={submit}>
        <span className="eyebrow ink"><ShieldCheck size={15} /> {t("auth.secure_access", "Secure operations access")}</span>
        <h2>{registerMode ? t("auth.create_account", "Create your account") : t("auth.welcome_back", "Welcome back")}</h2>
        <p>{registerMode ? t("auth.register_subtitle", "Join the response operations network.") : t("auth.signin_subtitle", "Sign in to your command center.")}</p>
        {registerMode && <Field label={t("auth.full_name", "Full name")} name="full_name" placeholder={t("auth.full_name_placeholder", "John Doe")} required />}
        <Field label={t("auth.email_address", "Email address")} name="email" type="email" placeholder={t("auth.email_placeholder", "you@example.com")} required />
        <Field label={t("auth.password", "Password")} name="password" type="password" placeholder="••••••••" minLength={8} required />
        {registerMode && <Field label={t("auth.confirm_password", "Confirm password")} name="confirm_password" type="password" placeholder="••••••••" required />}
        {message && <div className={message.toLowerCase().includes("success") ? "notice success" : "notice"}>{message}</div>}
        <button className="button primary full" disabled={busy}>{busy ? t("auth.please_wait", "Please wait…") : registerMode ? t("auth.create_account", "Create account") : t("auth.sign_in", "Sign in")} <ChevronRight size={17} /></button>
        <p className="auth-switch">{registerMode ? t("auth.already_have_account", "Already have an account?") : t("auth.new_to_responda", "New to Responda?")} <button type="button" onClick={() => { setRegisterMode(!registerMode); navigate(registerMode ? "/login" : "/register"); }}>{registerMode ? t("auth.login", "Sign in") : t("auth.register", "Create account")}</button></p>
      </form>
    </section>
  </main>;
}

function ProtectedLayout({ context, onLanguage }: { context: AppContext; onLanguage: (value: string) => void }) {
  const [open, setOpen] = useState(false);
  const location = useLocation();
  const nav = [
    ["/", LayoutDashboard, "dashboard.title", "Dashboard"], ["/reports", ClipboardList, "navigation.disaster_reports", "Disaster reports"],
    ["/resources", Boxes, "navigation.resource_management", "Resource management"], ["/warehouses", WarehouseIcon, "navigation.warehouse_directory", "Warehouses"],
    ["/teams", Users, "navigation.response_teams", "Response teams"], ["/volunteers", HeartPulse, "navigation.volunteers", "Volunteers"],
    ["/live-map", MapPinned, "navigation.live_map", "Live map"], ["/analytics", Activity, "navigation.monitoring", "Analytics"],
    ["/notifications", Bell, "navigation.notifications", "Notifications"], ["/knowledge", Sparkles, "navigation.knowledge", "Knowledge base"],
  ] as const;
  return <div className="app-shell">
    <aside className={open ? "sidebar open" : "sidebar"}>
      <Link className="brand" to="/"><span className="brand-mark"><HeartPulse size={19} /></span><span className="brand-title">{context.t("navigation.brand", "Disaster Management")}</span></Link>
      <p className="nav-label">{context.t("navigation.operations", "Command center")}</p>
      <nav>{nav.map(([path, Icon, key, fallback]) => <Link key={path} onClick={() => setOpen(false)} className={location.pathname === path ? "nav-link active" : "nav-link"} to={path}><Icon size={18} /><span>{context.t(key, fallback)}</span></Link>)}</nav>
      <div className="sidebar-footer"><Link className="nav-link" to="/profile"><CircleUserRound size={18} />{context.t("navigation.profile", "Profile")}</Link><button className="nav-link" onClick={context.signOut}><LogOut size={18} />{context.t("navigation.logout", "Log out")}</button></div>
    </aside>
    <main className="main-content">
      <header className="topbar"><button className="icon-button mobile-menu" onClick={() => setOpen(!open)}>{open ? <X /> : <Menu />}</button><div className="topbar-spacer" /><select className="language-select" value={context.language} onChange={(e) => onLanguage(e.target.value)}>{context.languages.map((item) => <option key={item.code} value={item.code}>{item.name}</option>)}</select><Link className="bell-button" to="/notifications" aria-label={context.t("navigation.notifications", "Notifications")}><Bell size={19} /></Link><Link className="profile-chip" to="/profile"><span>{context.session.user.full_name.split(" ").map((name) => name[0]).slice(0, 2).join("")}</span><small>{context.session.user.full_name}</small></Link></header>
      <div className="page-content"><PageRouter context={context} /></div>
      <GlobalNotifications context={context} />
    </main>
  </div>;
}

function PageRouter({ context }: { context: AppContext }) {
  return <Routes>
    <Route index element={<Dashboard context={context} />} /><Route path="reports" element={<ReportsPage context={context} />} /><Route path="reports/new" element={<CreateReport context={context} />} /><Route path="reports/:id" element={<ReportDetail context={context} />} />
    <Route path="resources" element={<ResourcesPage context={context} />} /><Route path="warehouses" element={<WarehousesPage context={context} />} /><Route path="teams" element={<TeamsPage context={context} />} /><Route path="volunteers" element={<VolunteersPage context={context} />} />
    <Route path="live-map" element={<LiveMapPage context={context} />} /><Route path="notifications" element={<NotificationsPage context={context} />} /><Route path="analytics" element={<AnalyticsPage context={context} />} /><Route path="knowledge" element={<KnowledgePage context={context} />} /><Route path="profile" element={<ProfilePage context={context} />} />
  </Routes>;
}

function Dashboard({ context }: { context: AppContext }) {
  const trends = useAsync(() => api.trends(context.session.token, context.language), [context.language]);
  const priority = useAsync(() => api.priority(context.session.token, context.language), [context.language]);
  const notifications = useAsync(() => api.notifications(context.session.token, context.language), [context.language]);
  const reports = useAsync(() => api.reports(context.session.token, context.language), [context.language]);
  useEffect(() => { const timer = window.setInterval(() => { void reports.refresh(true); void priority.refresh(true); void notifications.refresh(true); }, 5000); return () => window.clearInterval(timer); }, [context.language]);
  const cards = [
    [AlertTriangle, context.t("dashboard.active_disasters", "Active disasters"), trends.data?.total_reports ?? "—", "rose"],
    [PackageCheck, context.t("dashboard.resource_availability", "Resource availability"), context.t("status.operational", "Operational"), "mint"],
    [AlertTriangle, context.t("dashboard.critical_shortages", "Critical shortages"), priority.data?.items.filter((item) => item.severity === "Critical").length ?? "—", "amber"],
    [Users, context.t("dashboard.field_response_teams", "Field response teams"), context.t("dashboard.live_roster", "Live roster"), "blue"],
  ] as const;
  return <><PageHeader eyebrow={context.t("dashboard.eyebrow", "Situation overview")} title={context.t("dashboard.title", "Dashboard")} subtitle={context.t("dashboard.subtitle", "Disaster Response Command Center")} action={<Link className="button primary" to="/reports/new"><Plus size={17} /> {context.t("disaster_reports.list.btn_report_disaster", "Report disaster")}</Link>} />
    <section className="metric-grid">{cards.map(([Icon, title, value, tone]) => <article className={"metric-card " + tone} key={title}><div className="metric-icon"><Icon size={20} /></div><span>{title}</span><strong>{value}</strong><small>{title === context.t("dashboard.active_disasters", "Active disasters") ? context.t("dashboard.updated_now", "Updated just now") : context.t("dashboard.operations_ready", "Operations ready")}</small></article>)}</section>
    <section className="dashboard-grid"><article className="panel span-two"><PanelTitle title={context.t("dashboard.recent_disaster_activity", "Recent disaster activity")} to="/reports" /><LoadState {...reports}>{reports.data?.length ? <div className="report-list">{reports.data.slice(0, 5).map((report) => <ReportRow key={report.id} report={report} context={context} />)}</div> : <Empty label={context.t("dashboard.no_active_disasters", "No active disasters right now.")} />}</LoadState></article>
    <article className="panel"><PanelTitle title={context.t("dashboard.critical_alerts", "Critical alerts")} to="/notifications" /><LoadState {...notifications}>{(() => { const unique = [...new Map((notifications.data || []).map((item) => [`${item.report_id || "general"}:${item.notification_type}:${item.title}`, item])).values()]; return unique.length ? unique.slice(0, 4).map((item) => <div className="alert-item" key={item.id}><span className={item.is_read ? "dot read" : "dot"} /><div><b>{item.title}</b><p>{item.message}</p></div></div>) : <Empty label={context.t("dashboard.no_critical_alerts", "No critical alerts.")} />; })()}</LoadState></article>
    <article className="panel span-two"><PanelTitle title={context.t("dashboard.priority_queue", "Priority response queue")} to="/analytics" /><LoadState {...priority}>{priority.data?.items.length ? <table><thead><tr><th>{context.t("dashboard.priority", "Priority")}</th><th>{context.t("dashboard.incident", "Incident")}</th><th>{context.t("common.population", "Population")}</th><th>{context.t("common.status", "Status")}</th></tr></thead><tbody>{priority.data.items.slice(0, 5).map((item) => <tr key={item.report_id}><td><b className="priority-score">{item.priority_score.toFixed(1)}</b></td><td><Link to={"/reports/" + item.report_id}>{translatedLabel(context, item.disaster_type)}</Link><small>#{item.report_id} · {translatedLabel(context, item.severity)}</small></td><td>{item.affected_population.toLocaleString()}</td><td><Status value={translatedLabel(context, item.current_status)} /></td></tr>)}</tbody></table> : <Empty label={context.t("dashboard.no_priorities", "No response priorities yet.")} />}</LoadState></article>
    <article className="panel"><PanelTitle title={context.t("dashboard.impact_by_incident", "Impact by incident type")} to="/analytics" /><LoadState {...trends}>{trends.data?.disaster_type_breakdown.map((item) => <div className="bar-row" key={item.disaster_type}><span>{translatedLabel(context, item.disaster_type)}</span><div><i style={{ width: Math.min(100, item.report_count * 18) + "%" }} /></div><b>{item.report_count}</b></div>) || <Empty label={context.t("dashboard.no_analytics", "No analytics yet.")} />}</LoadState></article></section></>;
}

function ReportsPage({ context }: { context: AppContext }) {
  const reports = useAsync(() => api.reports(context.session.token, context.language), [context.language]);
  useEffect(() => { const timer = window.setInterval(() => void reports.refresh(true), 5000); return () => window.clearInterval(timer); }, [context.language]);
  const [query, setQuery] = useState("");
  const filtered = reports.data?.filter((item) => [item.disaster_type, item.id].join(" ").toLowerCase().includes(query.toLowerCase())) || [];
  return <><PageHeader eyebrow={context.t("reports.eyebrow", "Incident management")} title={context.t("disaster_reports.list.page_title", "Disaster Reports")} subtitle={context.t("reports.subtitle", "Monitor, assess, and coordinate every active incident.")} action={<Link className="button primary" to="/reports/new"><Plus size={17} /> {context.t("disaster_reports.list.btn_report_disaster", "Report disaster")}</Link>} />
    <article className="panel"><div className="table-toolbar"><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder={context.t("disaster_reports.list.search_placeholder", "Search by type or report ID…")} /><button className="button ghost" onClick={() => void reports.refresh()}><RefreshCw size={16} /> {context.t("common.refresh", "Refresh")}</button></div><LoadState {...reports}>{filtered.length ? <table><thead><tr><th>{context.t("common.report_id", "Report")}</th><th>{context.t("disaster_reports.table.col_magnitude", "Magnitude")}</th><th>{context.t("common.affected", "Affected")}</th><th>{context.t("disaster_reports.table.col_impact", "Impact score")}</th><th>{context.t("common.status", "Status")}</th><th /></tr></thead><tbody>{filtered.map((report) => <tr key={report.id}><td><b>{translatedLabel(context, report.disaster_type)}</b><small>#{report.id} · {date(report.created_at)}</small></td><td>{report.magnitude}</td><td>{report.affected_population.toLocaleString()}</td><td>{report.predicted_impact_score?.toFixed(1) ?? context.t("disaster_reports.details.header.not_predicted", "Not predicted")}</td><td><Status value={translatedLabel(context, report.current_status || "reported")} /></td><td><Link className="text-link" to={"/reports/" + report.id}>{context.t("common.open", "Open")} <ChevronRight size={15} /></Link></td></tr>)}</tbody></table> : <Empty label={context.t("reports.empty", "No disaster reports yet. Start by reporting an incident.")} />}</LoadState></article></>;
}

function CreateReport({ context }: { context: AppContext }) {
  const navigate = useNavigate(); const [error, setError] = useState(""); const [busy, setBusy] = useState(false);
  const submit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); setBusy(true); setError(""); const form = new FormData(event.currentTarget); try { const report = await api.createReport({ disaster_type: form.get("disaster_type"), latitude: Number(form.get("latitude")), longitude: Number(form.get("longitude")), magnitude: Number(form.get("magnitude")), affected_population: Number(form.get("affected_population")) }, context.session.token, context.language); navigate("/reports/" + report.id); } catch (cause) { setError(cause instanceof Error ? cause.message : "Unable to submit report."); } finally { setBusy(false); } };
  return <><PageHeader eyebrow={context.t("report_form.eyebrow", "New field report")} title={context.t("disaster_reports.create.page_title", "Report a disaster")} subtitle={context.t("disaster_reports.create.page_subtitle", "Live weather and infrastructure data will be enriched automatically.")} /><form className="form-card" onSubmit={submit}><div className="form-grid"><Select label={context.t("disaster_reports.create.field_type", "Disaster type")} name="disaster_type" options={["flood", "earthquake", "cyclone", "drought", "wildfire"]} context={context} /><Field label={context.t("disaster_reports.create.field_latitude", "Latitude")} name="latitude" type="number" step="any" placeholder="13.0827" required /><Field label={context.t("disaster_reports.create.field_longitude", "Longitude")} name="longitude" type="number" step="any" placeholder="80.2707" required /><Field label={context.t("disaster_reports.create.field_magnitude", "Magnitude / intensity")} name="magnitude" type="number" step="0.1" min="0.1" max="15" placeholder="6.2" required /><Field label={context.t("disaster_reports.create.field_population", "Affected population")} name="affected_population" type="number" min="1" placeholder="1200" required /></div>{error && <div className="notice">{error}</div>}<div className="form-actions"><Link className="button ghost" to="/reports">{context.t("common.cancel", "Cancel")}</Link><button className="button primary" disabled={busy}>{busy ? context.t("disaster_reports.create.btn_submitting", "Submitting…") : context.t("disaster_reports.create.btn_submit_report", "Submit report")} <ChevronRight size={17} /></button></div></form></>;
}

function ReportDetail({ context }: { context: AppContext }) {
  const { id = "" } = useParams(); const reportId = Number(id); const report = useAsync(() => api.report(reportId, context.session.token, context.language), [reportId, context.language]); const timeline = useAsync(() => api.timeline(reportId, context.session.token, context.language), [reportId, context.language]);
  const reservations = useAsync(() => api.reservations(reportId, context.session.token, context.language), [reportId, context.language]);
  const [prediction, setPrediction] = useState<number>(); const [allocation, setAllocation] = useState<Allocation>(); const [active, setActive] = useState("overview"); const [notice, setNotice] = useState("");
  const run = async (task: "predict" | "allocate") => { setNotice(""); try { if (task === "predict") setPrediction((await api.predict(reportId, context.session.token, context.language)).predicted_impact_score); else { setAllocation(await api.allocate(reportId, context.session.token, context.language)); await reservations.refresh(); } await Promise.all([report.refresh(), timeline.refresh()]); } catch (cause) { setNotice(cause instanceof Error ? cause.message : "Action failed."); } };
  useEffect(() => { const timer = window.setInterval(() => { void timeline.refresh(true); void report.refresh(true); }, 5000); return () => window.clearInterval(timer); }, [reportId, context.language]);
  const shelters = useAsync(() => active === "shelters" ? api.shelters(reportId, context.session.token, context.language) : Promise.resolve(undefined), [active, reportId, context.language]);
  const route = useAsync(() => active === "route" ? api.route(reportId, context.session.token, context.language) : Promise.resolve(undefined), [active, reportId, context.language]);
  return <LoadState {...report}>{report.data && <><PageHeader eyebrow={`${context.t("common.report_id", "Report")} #${report.data.id}`} title={translatedLabel(context, report.data.disaster_type)} subtitle={`${context.t("disaster_reports.table.col_date", "Reported")} ${date(report.data.created_at)}`} action={<Status value={translatedLabel(context, report.data.current_status || "reported")} />} /><div className="detail-hero"><div><span>{context.t("disaster_reports.details.header.population_affected", "Affected population")}</span><b>{report.data.affected_population.toLocaleString()}</b></div><div><span>{context.t("disaster_reports.details.overview.magnitude", "Magnitude")}</span><b>{report.data.magnitude}</b></div><div><span>{context.t("disaster_reports.details.header.impact_score", "Impact score")}</span><b>{prediction?.toFixed(1) || report.data.predicted_impact_score?.toFixed(1) || "—"}</b></div><div><span>{context.t("report_detail.coordinates", "Coordinates")}</span><b>{report.data.latitude.toFixed(3)}, {report.data.longitude.toFixed(3)}</b></div></div><div className="tab-bar">{(["overview", "prediction", "allocation", "timeline", "route", "shelters"] as const).map((tab) => <button className={active === tab ? "active" : ""} onClick={() => setActive(tab)} key={tab}>{context.t(`disaster_reports.details.sections.${tab === "route" ? "routes" : tab}`, label(tab))}</button>)}</div>{notice && <div className="notice">{notice}</div>}
    {active === "overview" && <section className="dashboard-grid"><article className="panel"><h3>{context.t("report_detail.incident_conditions", "Incident conditions")}</h3><dl className="key-values"><div><dt>{context.t("common.temperature", "Temperature")}</dt><dd>{report.data.temperature ?? "—"} °C</dd></div><div><dt>{context.t("common.humidity", "Humidity")}</dt><dd>{report.data.humidity ?? "—"}%</dd></div><div><dt>{context.t("disaster_reports.details.weather.wind_speed", "Wind speed")}</dt><dd>{report.data.wind_speed ?? "—"} km/h</dd></div><div><dt>{context.t("common.status", "Status")}</dt><dd><Status value={translatedLabel(context, report.data.current_status || "reported")} /></dd></div></dl></article><article className="panel"><h3>{context.t("report_detail.recommended_action", "Recommended next action")}</h3><p>{context.t("report_detail.recommended_action_text", "Run impact prediction to estimate resource requirements, then allocate the available inventory from the nearest warehouse.")}</p><div className="button-stack"><button className="button primary" onClick={() => void run("predict")}><Sparkles size={16} /> {context.t("disaster_reports.details.prediction.btn_predict", "Run prediction")}</button><button className="button secondary" onClick={() => void run("allocate")}><PackageCheck size={16} /> {context.t("disaster_reports.details.allocation.btn_allocate", "Allocate resources")}</button></div></article></section>}
    {active === "prediction" && <PredictionPanel reportId={reportId} context={context} score={prediction || report.data.predicted_impact_score} onRun={() => void run("predict")} />}
    {active === "allocation" && <AllocationPanel context={context} allocation={allocation || (reservations.data?.[0]?.allocations ? { nearest_warehouse_name: reservations.data[0].items[0]?.warehouse_name || context.t("report_detail.operational_warehouse", "Operational warehouse"), nearest_warehouse_distance_km: 0, allocation_status: reservations.data[0].allocation_status || "Partial", allocations: reservations.data[0].allocations } : undefined)} onRun={() => void run("allocate")} />}
    {active === "timeline" && <article className="panel timeline"><h3>{context.t("disaster_reports.details.timeline.section_title", "Response timeline")}</h3><LoadState {...timeline}>{timeline.data?.map((item) => <div className="timeline-item" key={item.id}><span /><div><b>{translatedLabel(context, item.status)}</b><p>{item.note || context.t("report_detail.status_updated", "Status updated")}</p><small>{date(item.created_at)}</small></div></div>) || <Empty label={context.t("disaster_reports.details.timeline.empty_message", "No timeline events yet.")} />}</LoadState></article>}
    {active === "route" && <article className="panel"><h3>{context.t("disaster_reports.details.route.section_title", "Delivery route")}</h3><LoadState {...route}>{route.data ? <dl className="key-values"><div><dt>{context.t("disaster_reports.details.route.warehouse_label", "Source warehouse")}</dt><dd>{route.data.warehouse_name}</dd></div><div><dt>{context.t("disaster_reports.details.route.distance_label", "Distance")}</dt><dd>{route.data.distance_km.toFixed(1)} km</dd></div><div><dt>{context.t("disaster_reports.details.route.duration_label", "Estimated duration")}</dt><dd>{route.data.duration_minutes.toFixed(0)} min</dd></div><div><dt>{context.t("disaster_reports.details.route.eta_label", "Estimated arrival")}</dt><dd>{date(route.data.estimated_arrival_at)}</dd></div><div><dt>{context.t("disaster_reports.details.route.safety_label", "Route safety")}</dt><dd><Status value={translatedLabel(context, route.data.route_safety_status)} /></dd></div></dl> : <Empty label={context.t("report_detail.route_empty", "Route data will appear here.")} />}</LoadState></article>}
    {active === "shelters" && <article className="panel"><h3>{context.t("disaster_reports.details.shelters.section_title", "Shelter allocation")}</h3><LoadState {...shelters}>{shelters.data ? <><div className="detail-hero compact"><div><span>{context.t("disaster_reports.details.shelters.allocated_column", "Allocated")}</span><b>{shelters.data.allocated_people}</b></div><div><span>{context.t("disaster_reports.details.shelters.waiting_people_label", "Waiting")}</span><b>{shelters.data.waiting_people}</b></div></div><table><thead><tr><th>{context.t("disaster_reports.details.shelters.shelter_column", "Shelter")}</th><th>{context.t("disaster_reports.details.shelters.distance_column", "Distance")}</th><th>{context.t("disaster_reports.details.shelters.capacity_column", "Available capacity")}</th><th>{context.t("disaster_reports.details.shelters.allocated_column", "Allocated")}</th></tr></thead><tbody>{shelters.data.shelters.map((item) => <tr key={item.shelter_id}><td>{item.name}</td><td>{item.distance_km.toFixed(1)} km</td><td>{item.available_capacity}</td><td>{item.allocated_people}</td></tr>)}</tbody></table></> : <Empty label={context.t("live_map.no_shelter_allocation", "No shelter allocation data.")} />}</LoadState></article>}</>}</LoadState>;
}

function PredictionPanel({ reportId, context, score, onRun }: { reportId: number; context: AppContext; score?: number; onRun: () => void }) { const data = useAsync(() => api.predict(reportId, context.session.token, context.language), [reportId, context.language]); return <article className="panel"><div className="split-title"><div><h3>{context.t("disaster_reports.details.prediction.section_title", "AI impact prediction")}</h3><p>{context.t("report_detail.prediction_subtitle", "Estimate response intensity and required resources.")}</p></div><button className="button primary" onClick={onRun}><Sparkles size={16} /> {context.t("report_detail.run_refresh", "Run / refresh")}</button></div><LoadState {...data}>{(data.data || score !== undefined) && <><div className="score-display">{(data.data?.predicted_impact_score ?? score)?.toFixed(1)}<span>{context.t("disaster_reports.details.prediction.score_label", "Predicted impact score")}</span></div>{data.data && <div className="resource-requirements">{Object.entries(data.data.estimated_requirements).map(([resource, quantity]) => <div key={resource}><span>{translatedLabel(context, resource)}</span><b>{quantity}</b></div>)}</div>}</>}</LoadState></article>; }
function AllocationPanel({ context, allocation, onRun }: { context: AppContext; allocation?: Allocation; onRun: () => void }) { return <article className="panel"><div className="split-title"><div><h3>{context.t("disaster_reports.details.allocation.section_title", "Resource allocation")}</h3><p>{allocation ? `${context.t("disaster_reports.details.allocation.nearest_warehouse", "Nearest")}: ${allocation.nearest_warehouse_name} · ${allocation.nearest_warehouse_distance_km.toFixed(1)} km` : context.t("disaster_reports.details.allocation.intro_text", "Allocate requirements from nearby stock.")}</p></div><button className="button primary" onClick={onRun}><PackageCheck size={16} /> {context.t("disaster_reports.details.allocation.btn_allocate", "Allocate")}</button></div>{allocation ? <table><thead><tr><th>{context.t("disaster_reports.details.allocation.resource_column", "Resource")}</th><th>{context.t("disaster_reports.details.allocation.required_column", "Required")}</th><th>{context.t("disaster_reports.details.allocation.allocated_column", "Allocated")}</th><th>{context.t("disaster_reports.details.allocation.shortage_column", "Shortage")}</th></tr></thead><tbody>{Object.entries(allocation.allocations).map(([name, item]) => <tr key={name}><td>{translatedLabel(context, name)}</td><td>{item.required}</td><td>{item.allocated}</td><td className={item.shortage ? "danger" : ""}>{item.shortage}</td></tr>)}</tbody></table> : <Empty label={context.t("report_detail.allocation_empty", "Run allocation to see the operational plan.")} />}</article>; }

function ResourcesPage({ context }: { context: AppContext }) { const stock = useAsync(() => api.stock(context.session.token, context.language), [context.language]); const [resource, setResource] = useState<string>(); const resources = useMemo(() => Object.entries((stock.data || []).reduce<Record<string, number>>((all, item) => { const name = String(item.resource || "Resource"); all[name] = (all[name] || 0) + Number(item.available_quantity || 0); return all; }, {})), [stock.data]); const matches = (stock.data || []).filter((item) => !resource || item.resource === resource); return <><PageHeader eyebrow={context.t("resources.eyebrow", "Supply intelligence")} title={context.t("navigation.resource_management", "Resource management")} subtitle={context.t("resources.live_stock_subtitle", "Live stock changes as operational allocations are made.")} /><section className="resource-summary"><LoadState {...stock}>{resources.map(([name, quantity]) => <button className={resource === name ? "resource-card active" : "resource-card"} onClick={() => setResource(resource === name ? undefined : name)} key={name}><span>{translatedLabel(context, name)}</span><b>{quantity}</b><small>{context.t("resources.available_across_network", "Available across network")}</small></button>)}</LoadState></section><article className="panel"><PanelTitle title={resource ? `${translatedLabel(context, resource)} ${context.t("resources.by_warehouse", "by warehouse")}` : context.t("resources.select_resource", "Select a resource to view its warehouses")} /><LoadState {...stock}>{resource ? <table><thead><tr><th>{context.t("common.warehouse", "Warehouse")}</th><th>{context.t("common.state", "State")}</th><th>{context.t("warehouses.available_quantity", "Available quantity")}</th></tr></thead><tbody>{matches.map((item, index) => <tr key={index}><td>{String(item.warehouse_name)}</td><td>{String(item.state || "—")}</td><td>{String(item.available_quantity ?? "—")}</td></tr>)}</tbody></table> : <Empty label={context.t("resources.choose_resource", "Choose a resource above to see the warehouses that hold it.")} />}</LoadState></article></>; }
function WarehousesPage({ context }: { context: AppContext }) { const warehouses = useAsync(() => api.warehouses(context.session.token, context.language), [context.language]); const [selected, setSelected] = useState<Warehouse>(); return <><PageHeader eyebrow={context.t("warehouses.eyebrow", "Distribution network")} title={context.t("navigation.warehouse_directory", "Warehouse directory")} subtitle={context.t("warehouses.subtitle", "Select a warehouse to inspect all of its live inventory.")} /><section className="card-grid"><LoadState {...warehouses}>{warehouses.data?.map((item) => <button className={selected?.warehouse_id === item.warehouse_id ? "warehouse-card selected" : "warehouse-card"} onClick={() => setSelected(item)} key={item.warehouse_id}><div className="card-icon"><WarehouseIcon size={20} /></div><span>{item.state}</span><h3>{item.warehouse_name}</h3><small>{item.latitude.toFixed(3)}, {item.longitude.toFixed(3)}</small><div className="inventory-chips">{item.inventory.slice(0, 4).map((stock) => <span key={stock.resource}>{translatedLabel(context, stock.resource)} <b>{stock.available_quantity}</b></span>)}</div></button>) || <Empty label={context.t("warehouses.empty_description", "No warehouses are available.")} />}</LoadState></section>{selected && <article className="panel warehouse-detail"><PanelTitle title={`${selected.warehouse_name} ${context.t("warehouses.inventory", "inventory")}`} /><table><thead><tr><th>{context.t("common.resource", "Resource")}</th><th>{context.t("warehouses.available_quantity", "Available quantity")}</th></tr></thead><tbody>{selected.inventory.map((item) => <tr key={item.resource}><td>{translatedLabel(context, item.resource)}</td><td>{item.available_quantity}</td></tr>)}</tbody></table></article>}</>; }
function TeamsPage({ context }: { context: AppContext }) { const teams = useAsync(() => api.teams(context.session.token, context.language), [context.language]); const [open, setOpen] = useState(false); const [error, setError] = useState(""); useEffect(() => { const timer = window.setInterval(() => void teams.refresh(true), 5000); return () => window.clearInterval(timer); }, [context.language]); const submit = async (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const values = Object.fromEntries(new FormData(e.currentTarget)); try { await api.createTeam(values, context.session.token, context.language); setOpen(false); await teams.refresh(); } catch (cause) { setError(cause instanceof Error ? cause.message : context.t("teams.failed_to_create", "Unable to create team.")); } }; return <><PageHeader eyebrow={context.t("teams.eyebrow", "Field operations")} title={context.t("teams.title", "Responder teams")} subtitle={context.t("teams.subtitle", "Build and coordinate teams available for deployment.")} action={<button className="button primary" onClick={() => setOpen(!open)}><Plus size={17} /> {context.t("teams.create", "Create team")}</button>} />{open && <form className="form-card inline-form" onSubmit={submit}><div className="form-grid"><Field label={context.t("teams.number", "Team number")} name="team_number" placeholder="TEAM-CHN-01" required /><Field label={context.t("teams.skills", "Skills")} name="skills" placeholder={context.t("teams.example_skills", "Medical, First Aid")} required /><Field label={context.t("teams.vehicles", "Vehicles")} name="vehicles" placeholder={context.t("teams.example_vehicles", "2 Ambulances")} /><Field label={context.t("teams.tags", "Tags")} name="tags" placeholder={context.t("teams.example_tags", "medical, emergency")} /></div>{error && <div className="notice">{error}</div>}<button className="button primary">{context.t("action.save", "Save team")}</button></form>}<section className="card-grid"><LoadState {...teams}>{teams.data?.map((team) => <TeamCard key={team.id} team={team} context={context} />) || <Empty label={context.t("teams.no_matching", "No teams have been created yet.")} />}</LoadState></section></>; }
function TeamCard({ team, context }: { team: Team; context: AppContext }) { return <article className="team-card"><div className="split-title"><div className="card-icon"><Users size={20} /></div><Status value={translatedLabel(context, team.status)} /></div><h3>{team.team_number}</h3><p>{translatedLabel(context, team.skills)}</p><small>{team.vehicles || context.t("teams.no_vehicle_details", "No vehicle details")} · {team.tags || context.t("teams.untagged", "Untagged")}</small><strong>{team.member_count} {context.t("teams.members", "members")}</strong></article>; }
function VolunteersPage({ context }: { context: AppContext }) { const volunteers = useAsync(() => api.volunteers(context.session.token, context.language), [context.language]); const [open, setOpen] = useState(false); const [error, setError] = useState(""); const submit = async (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const raw = Object.fromEntries(new FormData(e.currentTarget)); try { await api.createVolunteer({ ...raw, latitude: Number(raw.latitude), longitude: Number(raw.longitude) }, context.session.token, context.language); setOpen(false); await volunteers.refresh(); } catch (cause) { setError(cause instanceof Error ? cause.message : context.t("volunteers.failed_to_add", "Unable to add volunteer.")); } }; return <><PageHeader eyebrow={context.t("volunteers.eyebrow", "Human response network")} title={context.t("navigation.volunteers", "Volunteers")} subtitle={context.t("volunteers.subtitle", "Manage field-ready individual responders.")} action={<button className="button primary" onClick={() => setOpen(!open)}><Plus size={17} /> {context.t("volunteers.add", "Add volunteer")}</button>} />{open && <form className="form-card inline-form" onSubmit={submit}><div className="form-grid"><Field label={context.t("common.name", "Name")} name="name" required /><Field label={context.t("auth.email_address", "Email")} name="email" type="email" required /><Field label={context.t("volunteers.phone", "Phone")} name="phone" required /><Field label={context.t("volunteers.skill", "Skill")} name="skill" required /><Field label={context.t("common.latitude", "Latitude")} name="latitude" type="number" step="any" required /><Field label={context.t("common.longitude", "Longitude")} name="longitude" type="number" step="any" required /></div>{error && <div className="notice">{error}</div>}<button className="button primary">{context.t("volunteers.add", "Add volunteer")}</button></form>}<article className="panel"><LoadState {...volunteers}>{volunteers.data?.length ? <table><thead><tr><th>{context.t("volunteers.responder", "Responder")}</th><th>{context.t("volunteers.skill", "Skill")}</th><th>{context.t("volunteers.contact", "Contact")}</th><th>{context.t("volunteers.availability", "Availability")}</th></tr></thead><tbody>{volunteers.data.map((item) => <tr key={item.id}><td><b>{item.name}</b><small>#{item.id}</small></td><td>{item.skill}</td><td>{item.email}<small>{item.phone}</small></td><td><Status value={translatedLabel(context, item.availability)} /></td></tr>)}</tbody></table> : <Empty label={context.t("volunteers.none", "No volunteers registered.")} />}</LoadState></article></>; }
function LiveMapPage({ context }: { context: AppContext }) {
  const reports = useAsync(() => api.reports(context.session.token, context.language), [context.language]);
  const warehouses = useAsync(() => api.warehouses(context.session.token, context.language), [context.language]);
  const [selected, setSelected] = useState<Report | Warehouse>(); const [vehicles, setVehicles] = useState<VehicleTracking[]>([]);
  const [risks, setRisks] = useState<RoadRisk[]>([]); const [routePlan, setRoutePlan] = useState<RoutePlan>(); const [vehicleError, setVehicleError] = useState("");
  const selectedReport = selected && "disaster_type" in selected ? selected : undefined;
  const points = [...(reports.data || []).map((item) => ({ ...item, kind: "incident" as const })), ...(warehouses.data || []).map((item) => ({ ...item, kind: "warehouse" as const }))];
  const refreshVehicles = async () => { if (!selectedReport) return; try { const [tracking, route, activeRisks] = await Promise.all([api.vehicleTracking(selectedReport.id, context.session.token, context.language), api.route(selectedReport.id, context.session.token, context.language), api.roadRisks(selectedReport.id, context.session.token, context.language)]); setVehicles(tracking); setRoutePlan(route); setRisks(activeRisks); } catch (cause) { setVehicleError(cause instanceof Error ? cause.message : "Unable to load vehicle tracking."); } };
  useEffect(() => { void refreshVehicles(); const timer = selectedReport ? window.setInterval(() => void refreshVehicles(), 5000) : undefined; return () => { if (timer) window.clearInterval(timer); }; }, [selectedReport?.id, context.language]);
  const simulate = async (action: "start" | "tick" | "roadblock") => { if (!selectedReport) return; setVehicleError(""); try { if (action === "start") setVehicles([await api.startVehicleSimulation(selectedReport.id, context.session.token, context.language)]); if (action === "tick") setVehicles(await api.advanceVehicleSimulation(selectedReport.id, context.session.token, context.language)); if (action === "roadblock") await api.simulateRoadblock(selectedReport.id, context.session.token, context.language); await refreshVehicles(); } catch (cause) { setVehicleError(cause instanceof Error ? cause.message : "Vehicle simulation failed."); } };
  const setSpeed = async (vehicle: VehicleTracking, speed: number) => { if (!selectedReport || !Number.isFinite(speed)) return; try { await api.updateVehicleTelemetry(selectedReport.id, vehicle.id, { speed_kmph: speed }, context.session.token, context.language); await refreshVehicles(); } catch (cause) { setVehicleError(cause instanceof Error ? cause.message : "Unable to update vehicle speed."); } };
  const activeRoute = vehicles[0]?.route_geometry || routePlan?.geometry; const routePoints = activeRoute?.coordinates.map(([longitude, latitude]) => [latitude, longitude] as [number, number]) || [];
  const rerouted = vehicles.some((vehicle) => vehicle.route_status === "rerouted");
  return <><PageHeader eyebrow={context.t("live_map.eyebrow", "Spatial operations view")} title={context.t("navigation.live_map", "Live map")} subtitle={context.t("live_map.subtitle", "India-wide disaster and warehouse locations in one operational picture.")} /><div className="map-layout"><article className="map-panel leaflet-map"><MapContainer center={[22.5937, 78.9629]} zoom={5} minZoom={4} scrollWheelZoom className="india-leaflet"><TileLayer attribution={context.t("live_map.map_attribution", "© OpenStreetMap contributors")} url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />{routePoints.length > 1 && <Polyline positions={routePoints} pathOptions={{ color: rerouted ? "#8b5cc7" : "#1976d2", weight: 6, opacity: 0.82 }} />}{risks.map((risk) => <CircleMarker key={`risk-${risk.id}`} center={[risk.latitude, risk.longitude]} radius={8} pathOptions={{ color: "#fff", weight: 2, fillColor: "#d9625d", fillOpacity: 1 }}><Popup><b>Road blockage</b><br />{risk.road_name || risk.description}</Popup></CircleMarker>)}{points.map((point) => <CircleMarker key={point.kind === "incident" ? `incident-${point.id}` : `warehouse-${point.warehouse_id}`} center={[point.latitude, point.longitude]} radius={10} pathOptions={{ color: "#fff", weight: 3, fillColor: point.kind === "incident" ? "#d9625d" : "#2779ae", fillOpacity: 1 }} eventHandlers={{ click: () => setSelected(point) }}><Popup><b>{point.kind === "incident" ? label(point.disaster_type) : point.warehouse_name}</b><br />{point.latitude.toFixed(3)}, {point.longitude.toFixed(3)}</Popup></CircleMarker>)}{vehicles.map((vehicle) => <CircleMarker key={`vehicle-${vehicle.id}`} center={[vehicle.latitude, vehicle.longitude]} radius={9} pathOptions={{ color: "#fff", weight: 3, fillColor: vehicle.route_status === "rerouted" ? "#8b5cc7" : "#1caa79", fillOpacity: 1 }}><Popup><b>{vehicle.team_number}</b><br />{vehicle.speed_kmph.toFixed(0)} km/h · ETA {date(vehicle.estimated_arrival_at)}</Popup></CircleMarker>)}</MapContainer><div className="map-legend"><span><i className="incident" /> {context.t("live_map.disasters", "Disasters")}</span><span><i className="warehouse" /> {context.t("live_map.warehouses", "Warehouses")}</span><span><i className="vehicle" /> Teams / vehicles</span></div></article><aside className="map-side panel"><h3>{selected ? ("disaster_type" in selected ? label(selected.disaster_type) : selected.warehouse_name) : context.t("live_map.operations_panel", "Operations panel")}</h3>{selected ? "disaster_type" in selected ? <><Status value={selected.current_status || "reported"} /><div className="button-stack"><button className="button primary" onClick={() => void simulate("start")}>Start assigned team</button><button className="button secondary" onClick={() => void simulate("tick")}>Advance route</button><button className="button ghost" onClick={() => void simulate("roadblock")}>Report roadblock</button></div>{routePlan && <p className="tracking-line">{rerouted ? "Rerouted from the latest vehicle position" : "Vehicle follows the planned road route"}</p>}{risks.map((risk) => <p className="tracking-line" key={risk.id}>⚠ Blockage: {risk.road_name || risk.description}</p>)}{vehicles.map((vehicle) => <div className="tracking-line" key={vehicle.id}><b>{vehicle.team_number}</b> · {vehicle.progress_percent}%<small>ETA: {date(vehicle.estimated_arrival_at)}</small><SpeedControl vehicle={vehicle} onSave={setSpeed} /></div>)}{vehicleError && <div className="notice">{vehicleError}</div>}<Link className="button secondary full" to={"/reports/" + selected.id}>{context.t("live_map.open_incident", "Open incident details")}</Link></> : <><Status value="Operational" /><p>{selected.state}</p><dl className="key-values">{selected.inventory.map((item) => <div key={item.resource}><dt>{label(item.resource)}</dt><dd>{item.available_quantity}</dd></div>)}</dl></> : <Empty label={context.t("live_map.select_marker", "Select a disaster or warehouse marker.")} />}</aside></div></>;
}
function SpeedControl({ vehicle, onSave }: { vehicle: VehicleTracking; onSave: (vehicle: VehicleTracking, speed: number) => Promise<void> }) { const [speed, setSpeed] = useState(String(vehicle.speed_kmph)); useEffect(() => setSpeed(String(vehicle.speed_kmph)), [vehicle.speed_kmph]); return <form className="speed-control" onSubmit={(event) => { event.preventDefault(); void onSave(vehicle, Number(speed)); }}><label>Speed <input aria-label={`${vehicle.team_number} speed`} type="number" min="0" max="240" value={speed} onChange={(event) => setSpeed(event.target.value)} /><span>km/h</span></label><button className="button ghost" type="submit">Update</button></form>; }
function GlobalNotifications({ context }: { context: AppContext }) { const [toast, setToast] = useState<Notification>(); const seenKey = `responda_notified_${context.session.user.id}`; useEffect(() => { let active = true; const poll = async () => { try { const notifications = await api.notifications(context.session.token, context.language); if (!active) return; const seen = new Set<number>(JSON.parse(localStorage.getItem(seenKey) || "[]")); const fresh = notifications.filter((item) => !item.is_read && !seen.has(item.id)).sort((a, b) => a.id - b.id); if (fresh.length) { seen.add(fresh[0].id); localStorage.setItem(seenKey, JSON.stringify([...seen].slice(-500))); setToast(fresh[0]); } } catch { /* A later poll will retry without interrupting the application. */ } }; void poll(); const interval = window.setInterval(() => void poll(), 5000); return () => { active = false; window.clearInterval(interval); }; }, [context.session.token, context.language, seenKey]); useEffect(() => { if (!toast) return; const timer = window.setTimeout(() => setToast(undefined), 5000); return () => window.clearTimeout(timer); }, [toast]); return toast ? <div className="notification-toast" role="status"><Bell size={18} /><div><b>{toast.title}</b><p>{toast.message}</p></div><i /></div> : null; }
function NotificationsPage({ context }: { context: AppContext }) { const data = useAsync(() => api.notifications(context.session.token, context.language), [context.language]); const mark = async (item: Notification) => { if (!item.is_read) { await api.markRead(item.id, context.session.token, context.language); await data.refresh(); } }; const unread = data.data?.filter((item) => !item.is_read) || []; const read = data.data?.filter((item) => item.is_read) || []; const list = (items: Notification[], empty: string) => items.length ? items.map((item) => <button className={item.is_read ? "notification read" : "notification"} key={item.id} onClick={() => void mark(item)}><span className="notification-icon"><Bell size={18} /></span><span><b>{item.title}</b><p>{item.message}</p><small>{date(item.created_at)} {item.report_id ? "· Report #" + item.report_id : ""}</small></span>{!item.is_read && <i />}</button>) : <Empty label={empty} />; return <><PageHeader eyebrow={context.t("notifications.eyebrow", "Operational signal")} title={context.t("notifications.title", "Notification center")} subtitle={context.t("notifications.subtitle", "Stay informed with disaster alerts and response updates.")} /><article className="panel notifications-panel"><h3>{context.t("notifications.new", "New notifications")}</h3><LoadState {...data}>{list(unread, context.t("notifications.none_new", "No new notifications."))}</LoadState></article><article className="panel notifications-panel read-section"><h3>{context.t("notifications.marked_read", "Marked as read")}</h3>{list(read, context.t("notifications.none_read", "No read notifications yet."))}</article></>; }
function AnalyticsPage({ context }: { context: AppContext }) { const trends = useAsync(() => api.trends(context.session.token, context.language), [context.language]); const priority = useAsync(() => api.priority(context.session.token, context.language), [context.language]); return <><PageHeader eyebrow={context.t("analytics.eyebrow", "Decision intelligence")} title={context.t("analytics.title", "Analytics")} subtitle={context.t("analytics.subtitle", "Track patterns, impact, and priority across reported incidents.")} /><LoadState {...trends}>{trends.data && <section className="metric-grid"><Metric title={context.t("analytics.total_reports", "Total reports")} value={trends.data.total_reports} icon={ClipboardList} /><Metric title={context.t("analytics.impact_predicted", "Impact predicted")} value={trends.data.predicted_reports} icon={Sparkles} /><Metric title={context.t("analytics.average_impact", "Average impact")} value={trends.data.average_impact_score?.toFixed(1) || "—"} icon={Activity} /><Metric title={context.t("disaster.affected_population", "Affected population")} value={trends.data.total_affected_population.toLocaleString()} icon={Users} /></section>}</LoadState><section className="dashboard-grid"><article className="panel span-two"><h3>{context.t("analytics.type_breakdown", "Disaster type breakdown")}</h3><LoadState {...trends}>{trends.data?.disaster_type_breakdown.map((item) => <div className="bar-row large" key={item.disaster_type}><span>{translatedLabel(context, item.disaster_type)}</span><div><i style={{ width: Math.min(100, item.report_count * 18) + "%" }} /></div><b>{item.report_count} {context.t("analytics.reports", "reports")}</b></div>)}</LoadState></article><article className="panel"><h3>{context.t("analytics.priority_queue", "Priority queue")}</h3><LoadState {...priority}>{priority.data?.items.slice(0, 5).map((item) => <Link className="mini-priority" to={"/reports/" + item.report_id} key={item.report_id}><b>{item.priority_score.toFixed(1)}</b><span>{translatedLabel(context, item.disaster_type)}<small>{translatedLabel(context, item.severity)} · #{item.report_id}</small></span></Link>)}</LoadState></article></section></>; }
function KnowledgePage({ context }: { context: AppContext }) { const data = useAsync(() => api.knowledge(context.session.token, context.language), [context.language]); const [open, setOpen] = useState(false); const [error, setError] = useState(""); const submit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const raw = Object.fromEntries(new FormData(event.currentTarget)); try { await api.createKnowledge({ title: String(raw.title), entry_type: String(raw.entry_type), content: String(raw.content), disaster_type: String(raw.disaster_type || "") || undefined, severity: String(raw.severity || "") || undefined, tags: String(raw.tags || "").split(",").map((tag) => tag.trim()).filter(Boolean) }, context.session.token, context.language); event.currentTarget.reset(); setOpen(false); await data.refresh(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Unable to save this knowledge entry."); } }; return <><PageHeader eyebrow={context.t("knowledge.eyebrow", "Response intelligence")} title={context.t("knowledge.title", "Knowledge base")} subtitle={context.t("knowledge.subtitle_create", "Capture field practices and lessons for future responses.")} action={<button className="button primary" onClick={() => setOpen(!open)}><Plus size={17} /> {context.t("knowledge.add", "Add knowledge")}</button>} />{open && <form className="form-card inline-form" onSubmit={submit}><div className="form-grid"><Field label={context.t("knowledge.title_label", "Title")} name="title" required minLength={3} placeholder={context.t("knowledge.title_placeholder", "Flood evacuation checkpoint plan")} /><Select label={context.t("knowledge.entry_type", "Entry type")} name="entry_type" options={["best_practice", "past_response", "lesson_learned"]} context={context} /><Field label={context.t("knowledge.disaster_type_optional", "Disaster type (optional)")} name="disaster_type" placeholder={context.t("disaster.flood", "Flood")} /><Select label={context.t("knowledge.severity_optional", "Severity (optional)")} name="severity" options={["", "Low", "Moderate", "High"]} /></div><label className="field"><span>{context.t("knowledge.guidance", "Guidance or lesson")}</span><textarea name="content" required minLength={10} placeholder={context.t("knowledge.guidance_placeholder", "Describe the field action, outcome, and what should be repeated or avoided.")} /></label><Field label={context.t("knowledge.tags", "Tags (comma separated)")} name="tags" placeholder={context.t("knowledge.tags_placeholder", "evacuation, medical, road-access")} />{error && <div className="notice">{error}</div>}<button className="button primary">{context.t("knowledge.save", "Save knowledge")}</button></form>}<section className="knowledge-grid"><LoadState {...data}>{data.data?.length ? data.data.map((entry) => <article className="knowledge-card" key={entry.id}><span>{translatedLabel(context, entry.entry_type)}</span><h3>{entry.title}</h3><p>{entry.content}</p><div>{entry.tags.map((tag) => <small key={tag}>#{tag}</small>)}</div></article>) : <Empty label={context.t("knowledge.empty_create", "No knowledge entries yet. Add a field practice, past response, or lesson learned above.")} />}</LoadState></section></>; }
function ProfilePage({ context }: { context: AppContext }) { const [name, setName] = useState(context.session.user.full_name); const [message, setMessage] = useState(""); const submit = async (event: FormEvent) => { event.preventDefault(); try { await api.updateMe({ full_name: name }, context.session.token, context.language); await context.refreshUser(); setMessage("Profile updated successfully."); } catch (cause) { setMessage(cause instanceof Error ? cause.message : "Profile update failed."); } }; return <><PageHeader eyebrow={context.t("profile.eyebrow", "Account settings")} title={context.t("profile.title", "My profile")} subtitle={context.t("profile.subtitle", "Manage your personal information and account preferences.")} /><section className="profile-layout"><article className="profile-card"><span className="profile-avatar">{context.session.user.full_name.split(" ").map((item) => item[0]).join("")}</span><h3>{context.session.user.full_name}</h3><p>{context.session.user.email}</p><Status value={context.t("profile.active_account", "Active account")} /><small>{context.t("profile.member_since", "Member since")} {date(context.session.user.created_at)}</small></article><form className="form-card" onSubmit={submit}><h3>{context.t("profile.personal_information", "Personal information")}</h3><p>{context.t("profile.email_unchangeable", "Your email address cannot be changed.")}</p><Field label={context.t("auth.email_address", "Email address")} name="email" value={context.session.user.email} disabled /><label className="field"><span>{context.t("auth.full_name", "Full name")}</span><input value={name} onChange={(event) => setName(event.target.value)} required minLength={2} /></label>{message && <div className={message.includes("success") ? "notice success" : "notice"}>{message}</div>}<button className="button primary">{context.t("profile.save_changes", "Save changes")}</button></form></section></>; }

function PageHeader({ eyebrow, title, subtitle, action }: { eyebrow: string; title: string; subtitle: string; action?: ReactNode }) { return <header className="page-header"><div><span className="eyebrow ink">{eyebrow}</span><h1>{title}</h1><p>{subtitle}</p></div>{action && <div className="page-action">{action}</div>}</header>; }
function Field({ label, name, type = "text", placeholder, required, minLength, min, max, step, value, disabled }: { label: string; name: string; type?: string; placeholder?: string; required?: boolean; minLength?: number; min?: string; max?: string; step?: string; value?: string; disabled?: boolean }) { return <label className="field"><span>{label}</span><input name={name} type={type} placeholder={placeholder} required={required} minLength={minLength} min={min} max={max} step={step} defaultValue={value} disabled={disabled} /></label>; }
function Select({ label, name, options, context }: { label: string; name: string; options: string[]; context?: AppContext }) { return <label className="field"><span>{label}</span><select name={name}>{options.map((item) => <option key={item} value={item}>{context ? translatedLabel(context, item) : labelText(item)}</option>)}</select></label>; }
function LoadState({ loading, error, children }: { loading: boolean; error: string; children: ReactNode }) { if (loading) return <div className="load-state"><RefreshCw className="spin" size={21} /> Loading operations data…</div>; if (error) return <div className="error-state"><AlertTriangle size={20} /><span>{error}</span></div>; return <>{children}</>; }
function Empty({ label }: { label: string }) { return <div className="empty"><Boxes size={26} /><p>{label}</p></div>; }
function PanelTitle({ title, to }: { title: string; to?: string }) { return <div className="panel-title"><h3>{title}</h3>{to && <Link to={to}>View all <ChevronRight size={15} /></Link>}</div>; }
function Metric({ title, value, icon: Icon }: { title: string; value: string | number; icon: typeof Activity }) { return <article className="metric-card blue"><div className="metric-icon"><Icon size={20} /></div><span>{title}</span><strong>{value}</strong><small>Live from your reports</small></article>; }
function ReportRow({ report, context }: { report: Report; context: AppContext }) { return <Link className="report-row" to={"/reports/" + report.id}><div className="report-symbol"><AlertTriangle size={17} /></div><div><b>{translatedLabel(context, report.disaster_type)}</b><small>#{report.id} · {date(report.created_at)}</small></div><Status value={translatedLabel(context, report.current_status || "reported")} /><ChevronRight size={17} /></Link>; }
function Status({ value }: { value: string }) { return <span className={"status " + value.toLowerCase().replace(/ /g, "-").replace(/_/g, "-")}>{label(value)}</span>; }
function label(value: string) { return value.replace(/_/g, " ").replace(/\b\w/g, (letter: string) => letter.toUpperCase()); }
function translatedLabel(context: AppContext, value: string) { const normalized = value.toLowerCase().replace(/[\s-]+/g, "_"); const prefixes = ["disaster", "status", "severity", "resource", "skill"]; for (const prefix of prefixes) { const key = `${prefix}.${normalized}`; const translated = context.t(key); if (translated !== key) return translated; } return label(value); }
function labelText(value: string) { return label(value); }
function date(value?: string) { return value ? new Date(value).toLocaleString([], { dateStyle: "medium", timeStyle: "short" }) : "—"; }

export default App;
